def transform(grid):
    """Keep non-background colors if they have ANY connected component of size >= 2."""
    rows, cols = len(grid), len(grid[0])

    # Find background (most frequent)
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    # Find connected components for each non-background color using flood fill
    def get_component(start_r, start_c, target_color):
        stack = [(start_r, start_c)]
        component = []
        visited = set()
        visited.add((start_r, start_c))

        while stack:
            r, c = stack.pop()
            component.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == target_color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
        return component

    # Find unique colors and check for large components
    from collections import defaultdict
    colors_seen = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                colors_seen.add(grid[r][c])

    colors_to_preserve = set()
    for color in colors_seen:
        # Find all disconnected components of this color
        visited_draw = set()
        connected = True
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r, c) not in visited_draw:
                    comp = get_component(r, c, color)
                    if len(comp) >= 2:
                        connected = True
                        colors_to_preserve.add(color)
                        break
            if connected:
                break

        if connected:
            colors_to_preserve.add(color)

    # Preserve all pixels of preserved colors
    result = [[background] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                if grid[r][c] in colors_to_preserve:
                    result[r][c] = grid[r][c]

    return result

