def transform(grid):
    """Remove colors whose connected components have very low fill ratio (< 0.88).
    Preserves background (color 1) and colors forming boundary-adjacent regions.
    """
    rows, cols = len(grid), len(grid[0])

    def get_component_pixels(color):
        visited = set()
        pixels = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r,c) not in visited:
                    stack = [(r,c)]
                    visited.add((r,c))
                    while stack:
                        cr, cc = stack.pop()
                        pixels.append((cr, cc))
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0<=nr<rows and 0<=nc<cols and grid[nr][nc] == color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                stack.append((nr,nc))
                    return pixels
        return pixels

    def check_fill_ratio(color):
        pixels = get_component_pixels(color)
        if not pixels:
            return 0
        r_min, r_max = min(p[0] for p in pixels), max(p[0] for p in pixels)
        c_min, c_max = min(p[1] for p in pixels), max(p[1] for p in pixels)
        bbox_area = (r_max - r_min + 1) * (c_max - c_min + 1)
        return len(pixels) / bbox_area if bbox_area > 0 else 0

    # Keep background (color 1) and colors with high fill ratio
    keep_colors = [1]
    for color in range(10):
        ratio = check_fill_ratio(color)
        if ratio >= 0.88:
            keep_colors.append(color)

    output = [[1]*cols for _ in range(rows)]
    for color in keep_colors:
        pixels = get_component_pixels(color)
        for r, c in pixels:
            output[r][c] = color

    return output

